// Reference solution
function patSim(pubIp, startPort, conns) {
  var map = {}, next = startPort, out = [];
  for (var i = 0; i < conns.length; i++) {
    var k = conns[i].proto + '|' + conns[i].ip + ':' + conns[i].port;
    if (map[k] === undefined) map[k] = next++;
    out.push(pubIp + ':' + map[k]);
  }
  return out;
}

